"""Semana 48 — Stolz auf, abhängig von (C1): adjetivos y sustantivos con preposición, verbos y adjetivos con genitivo."""
from base import q, ch, li, cz, tr, ty, MAY  # noqa: F401


def V(*xs):
    """Las respuestas, cada una también sin comas (la app no perdona una coma de menos)."""
    out = []
    for x in xs:
        for y in (x, x.replace(",", "")):
            if y not in out:
                out.append(y)
    return out


